Handle operator persistence on upgrade:

1. Add version/epoch to operator approvals
2. Implement revokeAll function for upgrades
3. Reset critical approvals in reinitializer

Example:
uint256 public approvalEpoch;
mapping(uint256 => mapping(address => mapping(address => bool))) operatorApprovals;

function setApprovalForAll(address op, bool approved) external {
operatorApprovals[approvalEpoch][msg.sender][op] = approved;
}

function _resetApprovals() internal {
approvalEpoch++; // Invalidates all previous approvals
}

